import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第四册：流利英语 · 单元 2 语法总结","description":"L9–L16 规则、例句、易错点。","frontmatter":{"title":"第四册：流利英语 · 单元 2 语法总结","description":"L9–L16 规则、例句、易错点。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","summary":"L9–L16 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 2：时间、条件与社会系统","link":"/life/english/new-concept/book-4/unit-02/overview"},"next":{"text":"第四册：流利英语 · 单元 2 单词与短语","link":"/life/english/new-concept/book-4/unit-02/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 2：时间、条件与社会系统","link":"/life/english/new-concept/book-4/unit-02/overview"},"next":{"text":"第四册：流利英语 · 单元 2 单词与短语","link":"/life/english/new-concept/book-4/unit-02/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/grammar.md","filePath":"life/english/new-concept/book-4/unit-02/grammar.md"}'),s={name:"life/english/new-concept/book-4/unit-02/grammar.md"};function r(i,e,h,l,p,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-单元-2-语法总结" tabindex="-1">第四册：流利英语 · 单元 2 语法总结 <a class="header-anchor" href="#第四册-流利英语-·-单元-2-语法总结" aria-label="Permalink to &quot;第四册：流利英语 · 单元 2 语法总结&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元复习与自测</a></p><h2 id="过去完成时与过去叙事参照点" tabindex="-1">过去完成时与过去叙事参照点 <a class="header-anchor" href="#过去完成时与过去叙事参照点" aria-label="Permalink to &quot;过去完成时与过去叙事参照点&quot;">​</a></h2><p>过去完成时 had done 表示早于某个过去参照点的动作，并不是所有“很久以前”的动作都要用它。先叙述收到消息，再回到消息形成的时刻，适合使用 had done；时间先后已经由 before 清楚表示时，一般过去时有时也可成立。进入回顾段落后不必每句机械重复过去完成时。过去完成时的否定为 had not done，不能再加 did。</p><p><strong>L9 原创例句：</strong> By the time the messenger arrived, the clerk had hidden the letter.</p><p>信使到达时，书记员已经藏起了信。</p><p><strong>易错：</strong> 不能仅因故事发生在古代就整篇用 had done；先确定两个过去动作的关系。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-009">Lesson 9</a></p><h2 id="比较结构与范围限定" tabindex="-1">比较结构与范围限定 <a class="header-anchor" href="#比较结构与范围限定" aria-label="Permalink to &quot;比较结构与范围限定&quot;">​</a></h2><p>more…than… 比较同一维度，as…as… 表示该维度相当。比较对象应对等，例如 the costs in Park A 与 those in Park B，而不是把成本与园区本身比较。the more…the more… 表示两个程度随之变化，但句型本身并不能证明因果。写产业说明时还要限定样本、时期和指标，不能从 more patents 直接推出 better companies。</p><p><strong>L10 原创例句：</strong> Office rents in the new district are lower than those in the city centre.</p><p>新区的办公室租金低于市中心的租金。</p><p><strong>易错：</strong> rents are lower than the city centre 把租金与地点比较，应补 those in。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-010">Lesson 10</a></p><h2 id="动名词短语作主语" tabindex="-1">动名词短语作主语 <a class="header-anchor" href="#动名词短语作主语" aria-label="Permalink to &quot;动名词短语作主语&quot;">​</a></h2><p>Keeping a journal 是一个活动概念，作主语时通常接单数谓语，即使短语内部带有复数宾语也不改变一致关系。两个不同活动由 and 连接时通常用复数谓语；如果构成一个整体概念则要结合语境判断。动名词主语强调活动本身，不等于现在进行时。主语较长时可以使用 It is useful to… 改写，但语气和信息重心会略有变化。</p><p><strong>L11 原创例句：</strong> Learning the names of local plants gives Mei a reason to walk outdoors.</p><p>认识当地植物的名称让梅有了去户外散步的理由。</p><p><strong>易错：</strong> Learning new skills are rewarding 中 are 应改 is；skills 只是动名词的宾语。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-011">Lesson 11</a></p><h2 id="unless-与条件从句" tabindex="-1">unless 与条件从句 <a class="header-anchor" href="#unless-与条件从句" aria-label="Permalink to &quot;unless 与条件从句&quot;">​</a></h2><p>unless 通常表示 if…not，即除非某条件成立，否则主句成立。The request will remain pending unless you sign. 意为不签字就继续待处理。unless 从句谈未来通常用一般现在时，不写 unless you will sign。并非所有含否定的 if 句都能机械改为 unless，尤其反事实或否定本身是讨论焦点时。阅读条款应先写出条件成立与不成立的两条结果，再检查逻辑。</p><p><strong>L12 原创例句：</strong> In this exercise, the request will remain pending unless the customer signs the form.</p><p>在本练习中，除非客户签署表格，否则申请将保持待处理状态。</p><p><strong>易错：</strong> unless the customer will sign 不用于这里的普通未来条件；应写 signs。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">Lesson 12</a></p><h2 id="目的不定式与-so-that" tabindex="-1">目的不定式与 so that <a class="header-anchor" href="#目的不定式与-so-that" aria-label="Permalink to &quot;目的不定式与 so that&quot;">​</a></h2><p>to、in order to 与 so as to 后接动词原形表达目的，通常与主句行为的执行者一致。so that 后接完整从句，适合主语不同或需要 can、could 等情态动词的情况。The team mapped the area to choose a site. 中测绘者和选择者相同。目的说明的是意图，不保证成功；to find oil 不能单凭语法推出确实找到了石油。否定目的可用 in order not to。</p><p><strong>L13 原创例句：</strong> The team collected rock samples so that specialists could compare the layers.</p><p>团队收集岩石样本，以便专家比较地层。</p><p><strong>易错：</strong> 不要把 to collect 与 because collected 混淆：前者说明目的，后者说明已经发生的原因。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">Lesson 13</a></p><h2 id="第二条件句与假设距离" tabindex="-1">第二条件句与假设距离 <a class="header-anchor" href="#第二条件句与假设距离" aria-label="Permalink to &quot;第二条件句与假设距离&quot;">​</a></h2><p>If + 一般过去时，主句 would/could/might + 动词原形，可以讨论与当前现实有距离的假设或较不确定的未来情形。过去形式在这里不一定指过去时间。If we changed the initial value, the model might produce a different result. 中 might 比 would 更谨慎。反事实过去通常使用 if had done 与 would have done，不能把两个时间框架随意混合。</p><p><strong>L14 原创例句：</strong> If we changed the starting value slightly, the two simulations might diverge over time.</p><p>如果我们稍微改变初始值，两次模拟可能会随时间逐渐分离。</p><p><strong>易错：</strong> 不要看到 changed 就一律解释成过去已发生；在本条件句里它表示假设距离。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">Lesson 14</a></p><h2 id="whether-引导名词性从句" tabindex="-1">whether 引导名词性从句 <a class="header-anchor" href="#whether-引导名词性从句" aria-label="Permalink to &quot;whether 引导名词性从句&quot;">​</a></h2><p>whether 可引导“是否”意义的主语、宾语或表语从句，后面采用陈述语序。We must decide whether the data can be shared. 不能写 whether can the data be shared。放在介词之后或接 to do 时一般用 whether，不用 if，例如 debate about whether…、whether to publish。whether…or… 可列出选择；它提出一个待解决问题，不表示作者已经选定其中一项。</p><p><strong>L15 原创例句：</strong> The team must decide whether the preliminary data can be shared with partners.</p><p>团队必须决定是否可以与合作伙伴共享初步数据。</p><p><strong>易错：</strong> whether can the data be shared 是错误疑问语序；嵌入从句用 whether the data can be shared。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">Lesson 15</a></p><h2 id="so-that-与-such-that-的结果表达" tabindex="-1">so…that 与 such…that 的结果表达 <a class="header-anchor" href="#so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;so…that 与 such…that 的结果表达&quot;">​</a></h2><p>so 后接形容词或副词，such 后接名词短语：so crowded that… 与 such a crowded street that…。so many/few 加可数复数，so much/little 加不可数名词，是需要单独记忆的数量结构。that 从句描述程度造成的结果，与表示目的的 so that 不同。阅读时要判断句中是否先有程度词；语法上写出结果也不能代替真实的因果证据。</p><p><strong>L16 原创例句：</strong> The crossing was so far away that several residents asked for a nearer one.</p><p>人行横道太远，以至于几位居民要求设置一个更近的。</p><p><strong>易错：</strong> such far away 结构错误；没有名词短语时应使用 so far away。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">Lesson 16</a></p>',50)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
